{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Outcome-driven wellness coaching with habit-based frameworks and soulful guidance by {{COACH_NAME}}, {{CREDENTIALS}}." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="aura-editorial">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="about.html">About</a>
        <a href="programs.html">Paths</a>
        <a href="services.html">Work With Me</a>
        <a href="pricing.html">Investment</a>
        <a href="testimonials.html">Stories</a>
        <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button class="nav-toggle" aria-label="Open navigation">☰</button>
    </div>
  </header>

  <!-- HERO (editorial, bold) -->
  <section class="hero">
    <div class="wrap hero-grid">
      <div class="hero-copy">
        <p class="eyebrow">Guided transformation</p>
        <h1>Design your days, reclaim your energy, become your truest self.</h1>
        <p class="lead">I help busy people translate values into daily practices. Small, consistent shifts that compound into thriving habits — without burnout.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="programs.html">Explore Paths</a>
        </div>
        <ul class="hero-meta">
          <li>Coach: {{COACH_NAME}}, {{CREDENTIALS}}</li>
          <li>Serving: {{CITY}}, {{STATE}}</li>
        </ul>
      </div>
      <div class="hero-art">
        <img src="assets/img/hero.svg" alt="Abstract mountain and sun illustration" />
        <div class="avatar">
          <img src="assets/img/avatar.svg" alt="{{COACH_NAME}} avatar" />
          <p>Hi, I’m {{COACH_NAME}} — I guide sustainable change through clarity, ritual, and integrity.</p>
        </div>
      </div>
    </div>
  </section>

  <!-- DIAGNOSTIC (lead magnet & quick audit) -->
  <section id="diagnostic" class="diagnostic wrap">
    <h2>Quick clarity diagnostic</h2>
    <p class="muted">A 90-second reflection to reveal which area needs a gentle habit reset.</p>
    <form id="diagnostic-form" class="diagnostic-form" aria-label="Wellness diagnostic">
      <label>Which area feels most out of balance?</label>
      <select name="area" required>
        <option value="energy">Energy & Sleep</option>
        <option value="stress">Stress & Boundaries</option>
        <option value="movement">Movement & Strength</option>
        <option value="nutrition">Daily Nutrition</option>
      </select>
      <label>How often do you follow a daily ritual?</label>
      <select name="ritual">
        <option value="rarely">Rarely</option>
        <option value="sometimes">Sometimes</option>
        <option value="regularly">Regularly</option>
      </select>
      <button class="btn" type="submit">Get my insight</button>
    </form>
    <div id="diagnostic-result" class="diagnostic-result hidden"></div>
  </section>

  <!-- PLAN (framework) -->
  <section class="plan wrap">
    <h2>My coaching framework: Compass & Habits</h2>
    <p class="muted">An editorial synthesis: alignment (why), architecture (what), action (when).</p>
    <div class="plan-grid">
      <article>
        <h3>Clarity (Compass)</h3>
        <p>We name what matters. Values become non-negotiables so choices become easier.</p>
      </article>
      <article>
        <h3>Structure (Architecture)</h3>
        <p>We design repeatable scaffolding: rituals, triggers, and micro-decisions that support momentum.</p>
      </article>
      <article>
        <h3>Practice (Action)</h3>
        <p>Small experiments over 4–8 weeks to test, iterate, and integrate new habits into life.</p>
      </article>
    </div>
  </section>

  <!-- MICRO_HABITS (action-focused list) -->
  <section id="micro-habits" class="micro-habits wrap">
    <h2>Micro-habits you can start this week</h2>
    <div class="habits">
      <div class="habit">
        <h4>2-minute reset</h4>
        <p>Pause mid-day: two deep breaths and a single intention to close the next hour.</p>
      </div>
      <div class="habit">
        <h4>Evening inventory</h4>
        <p>One-sentence note: what went well today and one tiny tweak for tomorrow.</p>
      </div>
      <div class="habit">
        <h4>Window walk</h4>
        <p>A 6–10 minute walk after lunch to shift energy and aid digestion.</p>
      </div>
      <div class="habit">
        <h4>Pairing ritual</h4>
        <p>Attach a new habit to an existing one (e.g., after coffee, three stretches).</p>
      </div>
    </div>
    <p class="muted">Micro-habits compound. Pick one, commit for seven days, then iterate.</p>
  </section>

  <!-- PRICING (overview) -->
  <section id="pricing" class="pricing wrap">
    <h2>Investment & Tiers</h2>
    <p class="muted">Straightforward options designed for clarity and measurable outcomes.</p>
    <div class="pricing-grid">
      <div class="tier">
        <h3>Starter Path</h3>
        <p class="price">$399</p>
        <ul>
          <li>4-week focused plan</li>
          <li>Weekly 30-min calls</li>
          <li>Email check-ins</li>
        </ul>
        <a class="btn" href="pricing.html">Choose Starter</a>
      </div>
      <div class="tier featured">
        <h3>Foundations</h3>
        <p class="price">$1,200</p>
        <ul>
          <li>8-week immersive program</li>
          <li>Weekly 50-min sessions + tools</li>
          <li>Personalized micro-habit plan</li>
        </ul>
        <a class="btn primary" href="pricing.html">Join Foundations</a>
      </div>
      <div class="tier">
        <h3>Deep Integration</h3>
        <p class="price">Bespoke</p>
        <ul>
          <li>12+ weeks, custom cadence</li>
          <li>Priority booking & VIP support</li>
          <li>Includes team/family onboarding if needed</li>
        </ul>
        <a class="btn" href="book.html">Request an invite</a>
      </div>
    </div>
  </section>

  <!-- CTA (final) -->
  <section class="cta wrap">
    <div class="cta-inner">
      <h2>Ready to begin? A simple next step.</h2>
      <p class="muted">Book a discovery conversation to see how a small habit sequence can change your months ahead.</p>
      <div class="cta-actions">
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn ghost" href="contact.html">Questions? Email {{EMAIL}}</a>
      </div>
    </div>
  </section>

  <footer class="site-footer">
    <div class="wrap footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p>{{TAGLINE}}</p>
      </div>
      <nav>
        <a href="about.html">About</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Pricing</a>
        <a href="testimonials.html">Testimonials</a>
      </nav>
      <div class="contact">
        <p>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
        <p>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
    <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}} · All rights reserved</p>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
