{"path":"assets/css/styles.css","content":"/* Aura editorial stylesheet — premium, high-contrast, bold scale */
:root{
  --bg:#fff;
  --text:#0b0b0b;
  --muted:#5b5b5b;
  --accent:#7b3fe4;
  --accent-2:#f7b733;
  --card:#fbfbfc;
  --glass:rgba(11,11,11,0.04);
}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial;line-height:1.45;color:var(--text);background:var(--bg);margin:0}
.wrap{max-width:1100px;margin:0 auto;padding:28px}
.site-header{border-bottom:1px solid var(--glass);background:linear-gradient(180deg, rgba(123,63,228,0.03), transparent)}
.site-header .wrap{display:flex;align-items:center;gap:16px}
.brand{font-weight:700;font-size:1.05rem;text-decoration:none;color:var(--text)}
.nav{margin-left:auto;display:flex;gap:14px;align-items:center}
.nav a{color:var(--text);text-decoration:none;padding:8px 10px;border-radius:6px}
.nav a.cta{background:var(--accent);color:#fff}
.nav-toggle{display:none;background:none;border:0;font-size:1.2rem}

.hero{padding:54px 0}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:32px;align-items:start}
.eyebrow{color:var(--accent);font-weight:700;text-transform:uppercase;letter-spacing:0.06em;margin:0}
.hero-copy h1{font-size:2.25rem;line-height:1.02;margin:8px 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-ctas .btn{margin-right:10px}
.hero-art{position:relative}
.hero-art img{width:100%;height:auto;border-radius:12px;box-shadow:0 8px 30px rgba(11,11,11,0.06)}
.avatar{display:flex;gap:12px;align-items:center;margin-top:14px}
.avatar img{width:72px;height:72px;border-radius:50%;border:4px solid #fff;box-shadow:0 6px 18px rgba(11,11,11,0.08)}
.hero-meta{list-style:none;padding:0;margin:12px 0 0;color:var(--muted)}
.hero-meta li{display:inline-block;margin-right:12px}

.diagnostic, .plan, .micro-habits, .pricing{padding:40px 0;border-top:1px solid var(--glass)}
.diagnostic-form{display:flex;gap:12px;align-items:center}
.diagnostic-form select{padding:10px;border-radius:8px;border:1px solid var(--glass)}
.diagnostic-form .btn{padding:10px 14px}
.diagnostic-result{margin-top:14px;padding:12px;border-radius:8px;background:linear-gradient(180deg,var(--card),#fff);box-shadow:inset 0 1px 0 rgba(255,255,255,0.6)}
.hidden{display:none}

.plan-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.plan-grid article{background:#fff;padding:18px;border-radius:12px;border:1px solid var(--glass)}

.micro-habits .habits{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}
.habit{background:linear-gradient(180deg,#fff, #fbfbfd);padding:16px;border-radius:10px;border:1px solid var(--glass)}
.habit h4{margin:0 0 8px}
.muted{color:var(--muted)}

.pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
.tier{background:#fff;padding:20px;border-radius:12px;border:1px solid var(--glass);text-align:center}
.tier.featured{transform:translateY(-6px);box-shadow:0 20px 40px rgba(123,63,228,0.08);border-color:rgba(123,63,228,0.12)}
.price{font-weight:700;font-size:1.25rem;margin:8px 0}
.btn{display:inline-block;padding:10px 16px;border-radius:8px;text-decoration:none;border:1px solid var(--glass);color:var(--text);background:#fff}
.btn.primary{background:var(--accent);color:#fff;border:0}
.btn.ghost{background:transparent;border:1px solid var(--glass)}
.btn.large{padding:14px 24px}

.cta{padding:40px 0;background-image:url('../assets/img/pattern.svg');background-repeat:no-repeat;background-position:right 20% top;}
.cta-inner{text-align:center;padding:28px;border-radius:12px;background:linear-gradient(180deg,rgba(123,63,228,0.03),transparent)}

.site-footer{border-top:1px solid var(--glass);padding:18px 0;margin-top:30px}
.footer-grid{display:flex;justify-content:space-between;align-items:flex-start}
.footer-grid nav a{display:block;color:var(--muted);text-decoration:none;margin-bottom:6px}
.copyright{font-size:0.9rem;color:var(--muted);text-align:center;margin-top:12px}

@media(max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .plan-grid,.pricing-grid{grid-template-columns:1fr}
  .nav{display:none}
  .nav-toggle{display:block;margin-left:auto}
}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactive behaviors: diagnostic, nav toggle, year
(function(){
  document.getElementById('year').textContent = new Date().getFullYear();

  // Mobile nav
  var toggle = document.querySelector('.nav-toggle');
  var nav = document.querySelector('.nav');
  if(toggle && nav){
    toggle.addEventListener('click', function(){
      nav.style.display = nav.style.display === 'flex' ? 'none' : 'flex';
    });
  }

  // Diagnostic quick-response
  var form = document.getElementById('diagnostic-form');
  var result = document.getElementById('diagnostic-result');
  if(form && result){
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var area = form.elements['area'].value;
      var ritual = form.elements['ritual'].value;
      var msg = '';
      if(area === 'energy') msg = 'Focus: gentle evening routines and a 14-day sleep-friendly window.';
      if(area === 'stress') msg = 'Focus: boundary scripting and two brief mid-day resets.';
      if(area === 'movement') msg = 'Focus: micro-strength sessions (10 minutes) paired with daily walking.';
      if(area === 'nutrition') msg = 'Focus: simple protein-forward breakfasts and hydration anchors.';
      if(ritual === 'rarely') msg += ' You’ll likely benefit from a daily pairing ritual to build momentum.';
      if(ritual === 'sometimes') msg += ' You have habits to refine — try 7-day consistency challenges.';
      if(ritual === 'regularly') msg += ' Great foundation — let’s iterate for alignment and next-level gains.';
      result.textContent = msg;
      result.classList.remove('hidden');
      result.scrollIntoView({behavior:'smooth',block:'center'});
    });
  }

  // Simple micro-habit toggles (local state)
  var habitBoxes = document.querySelectorAll('.habit');
  habitBoxes.forEach(function(h,idx){
    h.addEventListener('click', function(){
      var key = 'habit-'+idx;
      var done = localStorage.getItem(key) === '1';
      if(done){
        localStorage.removeItem(key);
        h.style.opacity = '1';
        h.style.transform='none';
      } else {
        localStorage.setItem(key,'1');
        h.style.opacity = '0.65';
        h.style.transform='translateY(2px)';
      }
    });
    // restore
    if(localStorage.getItem('habit-'+idx) === '1'){
      h.style.opacity = '0.65';
      h.style.transform='translateY(2px)';
    }
  });
})();
"} 
